cd /workspace/tmp && cat > gen.mjs <<'EOF'
// restricted growth strings of length 5 -> canonical set partitions
const out=[];
function rec(cur,max){
  if(cur.length===5){out.push(cur.slice());return;}
  for(let v=1;v<=max+1;v++){cur.push(v);rec(cur,Math.max(max,v));cur.pop();}
}
rec([],0);
console.error("count="+out.length);
for(const p of out) console.log(p.join(' '));
EOF
node gen.mjs > partitions.txt; wc -l partitions.txt; head -5 partitions.txt
